# For searching, we need a worker function that has access to the index
# We can use an initializer to set a global index in each worker process
_worker_index = None
_worker_doc_titles = None

def _init_search_worker(index, documents):
    global _worker_index, _worker_doc_titles
    _worker_index = index
    if documents:
        _worker_doc_titles = {d.doc_id: d.title for d in documents}
    else:
        _worker_doc_titles = {}

def _search_worker(query_args):
    query, top_k = query_args

    # Tokenize query
    query_tokens = tokenize(query)
    if not query_tokens:
        return []

    # Compute query TF
    query_tf = compute_term_frequencies(query_tokens)

    # Compute query TF-IDF vector
    query_vector = {}
    query_norm_squared = 0.0
    for term, tf in query_tf.items():
        if term in _worker_index.idf:
            tfidf = tf * _worker_index.idf[term]
            query_vector[term] = tfidf
            query_norm_squared += tfidf * tfidf

    if not query_vector:
        return []

    query_norm = math.sqrt(query_norm_squared)

    # Find candidate documents
    candidate_docs = set()
    for term in query_vector:
        if term in _worker_index.inverted_index:
            for doc_id, _ in _worker_index.inverted_index[term]:
                candidate_docs.add(doc_id)

    # Compute cosine similarity
    scores = []
    for doc_id in candidate_docs:
        doc_vector = _worker_index.doc_vectors.get(doc_id, {})
        doc_norm = _worker_index.doc_norms.get(doc_id, 0)

        if doc_norm == 0:
            continue

        dot_product = sum(query_vector.get(term, 0) * doc_vector.get(term, 0) for term in query_vector)
        similarity = dot_product / (query_norm * doc_norm)
        scores.append((doc_id, similarity))

    top_results = nlargest(top_k, scores, key=lambda x: x[1])

    results = []
    for doc_id, score in top_results:
        results.append(SearchResult(doc_id=doc_id, score=score, title=_worker_doc_titles.get(doc_id, f"Document {doc_id}")))

    return results

