            if r_seq.doc_id != r_par.doc_id:
                return False, f"Query {i}, Result {j}: Different doc_id: {r_seq.doc_id} vs {r_par.doc_id}"
            if abs(r_seq.score - r_par.score) > 1e-9:
                return False, f"Query {i}, Result {j}: Different score: {r_seq.score} vs {r_par.score}"

    return True, "Identical"

def compare_indices(idx_seq, idx_par):
    if idx_seq.num_documents != idx_par.num_documents:
        return False, "num_documents mismatch"
    if idx_seq.vocabulary != idx_par.vocabulary:
        return False, "vocabulary mismatch"
    if idx_seq.document_frequencies != idx_par.document_frequencies:
        return False, "document_frequencies mismatch"
    if idx_seq.idf != idx_par.idf:
        return False, "idf mismatch"
    if idx_seq.doc_norms.keys() != idx_par.doc_norms.keys():
        return False, "doc_norms keys mismatch"
    for doc_id in idx_seq.doc_norms:
        if abs(idx_seq.doc_norms[doc_id] - idx_par.doc_norms[doc_id]) > 1e-9:
            return False, f"doc_norms mismatch for doc {doc_id}"

    # Check inverted index
    if idx_seq.inverted_index.keys() != idx_par.inverted_index.keys():
        return False, "inverted_index keys mismatch"
    for term in idx_seq.inverted_index:
        if len(idx_seq.inverted_index[term]) != len(idx_par.inverted_index[term]):
            return False, f"inverted_index length mismatch for term {term}"
        for (d1, s1), (d2, s2) in zip(idx_seq.inverted_index[term], idx_par.inverted_index[term]):
            if d1 != d2 or abs(s1 - s2) > 1e-9:
                return False, f"inverted_index mismatch for term {term}"

    return True, "Identical"

def run_benchmark():
    num_docs = 5000
    num_queries = 1000
    num_workers = 4

    print(f"Generating corpus with {num_docs} documents...")
    documents = generate_corpus(num_docs, seed=42)

    queries = ["machine learning", "distributed systems", "data science", "cloud computing", "algorithms"] * (num_queries // 5)

    print("\n--- Indexing Benchmark ---")
    start = time.perf_counter()
    res_seq = build_tfidf_index_sequential(documents)
    t_seq_idx = time.perf_counter() - start
    print(f"Sequential indexing: {t_seq_idx:.4f}s")

    start = time.perf_counter()
    res_par = build_tfidf_index_parallel(documents, num_workers=num_workers)
    t_par_idx = time.perf_counter() - start
    print(f"Parallel indexing ({num_workers} workers): {t_par_idx:.4f}s")
    print(f"Speedup: {t_seq_idx / t_par_idx:.2f}x")

    idx_ok, idx_msg = compare_indices(res_seq.index, res_par.index)
    print(f"Indices match: {idx_ok} ({idx_msg})")

    print("\n--- Search Benchmark ---")
    start = time.perf_counter()
    results_seq = batch_search_sequential(queries, res_seq.index, documents=documents)
    t_seq_search = time.perf_counter() - start
    print(f"Sequential search: {t_seq_search:.4f}s")

    results_par, t_par_search = batch_search_parallel(queries, res_par.index, num_workers=num_workers, documents=documents)
    print(f"Parallel search ({num_workers} workers): {t_par_search:.4f}s")
    print(f"Speedup: {t_seq_search / t_par_search:.2f}x")

    search_ok, search_msg = compare_results(results_seq, results_par)
    print(f"Search results match: {search_ok} ({search_msg})")

if __name__ == "__main__":
    run_benchmark()
